def totals(csv_text):
    rows = csv_text.splitlines()
    if not rows:
        return {}
    name, amount = rows[0].split(",")
    totals = {}
    for row in rows[1:]:
        if row.strip():
            name, amount = row.split(",")
            totals[name] = totals.get(name, 0) + Decimal(str(amount))
    return totals

